<template><div><div class="page-title"><div><h1>可视化排班表</h1><p>按规则一键生成，也可直接手动调整班次。</p></div><el-button type="primary" @click="generate">一键生成本周</el-button></div><el-card><div class="filters"><el-select v-model="department" placeholder="科室" style="width:180px"><el-option v-for="item in departments" :key="item.id" :value="item.id" :label="item.name"/></el-select><el-date-picker v-model="range" type="daterange" value-format="YYYY-MM-DD"/><el-button @click="load">筛选</el-button></div><ScheduleLegend/><el-table :data="schedules" :row-class-name="rowClass"><el-table-column label="日期" width="150"><template #default="scope">{{scope.row.work_date.slice(0,10)}}</template></el-table-column><el-table-column label="人员" width="150"><template #default="scope">{{scope.row.staff?.name}}</template></el-table-column><el-table-column label="班次"><template #default="scope"><el-select v-model="scope.row.shift_id" size="small" @change="update(scope.row)"><el-option v-for="shift in shifts" :key="shift.id" :value="shift.id" :label="shift.name"/></el-select></template></el-table-column><el-table-column prop="note" label="备注"/></el-table></el-card></div></template>
<script setup lang="ts">
import {onMounted, ref} from 'vue'; import {ElMessage} from 'element-plus'; import api from '../api/http'; import ScheduleLegend from '../components/ScheduleLegend.vue'
const departments=ref<any[]>([]), schedules=ref<any[]>([]), shifts=ref([{id:1,name:'白班'},{id:2,name:'中班'},{id:3,name:'夜班'},{id:4,name:'休息'}]), department=ref(1), range=ref<string[]>([new Date().toISOString().slice(0,10),new Date(Date.now()+6*86400000).toISOString().slice(0,10)])
async function load(){schedules.value=await api.get('/schedules',{params:{department_id:department.value,from:range.value[0],to:range.value[1]}})}
async function generate(){try{await api.post('/schedules/generate',{department_id:department.value,start_date:range.value[0],end_date:range.value[1]});ElMessage.success('排班已生成');await load()}catch(error:any){ElMessage.error(error.message)}}
async function update(row:any){try{await api.put(`/schedules/${row.id}`,{shift_id:row.shift_id,note:row.note||''});ElMessage.success('班次已调整');await load()}catch(error:any){ElMessage.error(error.message)}}
function rowClass({row}:{row:any}){return `shift-${row.shift?.kind||''}`}; onMounted(async()=>{departments.value=await api.get('/departments');await load()})
</script>